NOTE = "**The P0 round (record l9t5, Slot A, 5 October 2026; the independent check V6's V6-m11).** Rows R-220 to R-245 add the drafts the P0 candidate composes that had no row (Slot C's containment of the supervisors on board B, R-245; record l8p's fail-safe delta on the guard, R-244; P0-7's board E solar sense, R-240, after the solar guard (route B2 is out of the baseline: no row); Slot C's T10 set point delta, R-242 and R-243, taken by SESSION L9T5-D9; record l8r2's d8v3, vbus20ov, fandec, panel5v, ph4, gndret and gndrtn on both boards; d8dec31's board D PTT draft; record l8p's guard; record l9t5's I-03, T10 and CAN SHDN drafts on both boards and the PA drain-current cap on boards A and D, F01 / D-17 PROVISIONAL; the efuse record's three settings), each with its order constraint; R-210 to R-212 (FAN_OK) are WITHDRAWN by the owner's rejection of FAN_OK, D-17's correction being R-227 and R-238. `l9t5_connected.py` composes boards A, B and D in this order and reads every record check on the result. d8dec31's PB network (R-193), a next-free taker, takes R603 and C607 on the full composition (R-194 still owes its fixed references). This table and the register are regenerated from `l4e9_power_path.py`'s change list; its other generated sections (5b, 29, outputs 10, 17 and 21) take these rows when L4-E9 itself is re-run, which on this tree refuses at its pin of L4-E11's output since the P0 base (L4-E9's delta, the coordinator's queue)."


def refuse(msg):
    sys.stderr.write("%s: %s; refusing\n" % (NAME, msg))
    sys.exit(3)


def patch_register(text):
    if "| R-220 |" in text:
        refuse("the register already carries R-220: applied before")
    new = text
    for anchor, rows in REG_ADD:
        m = re.search(r"^\| %s \|.*\n" % re.escape(anchor), new, re.M)
        if not m:
            refuse("the register has no row %s to follow" % anchor)
        new = new[:m.end()] + "".join(rows) + new[m.end():]
    for old, rep in REG_EDITS:
        if new.count(old) != 1:
            refuse("a FAN_OK row is not the expected text: %r" % old[:40])
        new = new.replace(old, rep)
    return new


def patch_script(text):
    new = text
    for old, rep in PY_EDITS:
        if new.count(old) != 1:
            refuse("the script's text occurs %d times, not once: %r" % (new.count(old), old[:70]))
        new = new.replace(old, rep)
    compile(new, "l4e9_power_path.py", "exec")
    return new


def module_of(source, path):
    """the patched script as a module whose __file__ is the target's own path (so it finds the target tree by git)"""
    m = types.ModuleType("l4e9_patched_%d" % abs(hash(path)))
    m.__file__ = path
    exec(compile(source, path, "exec"), m.__dict__)
    return m


def patch_page(text, m, reg_text):
    ch = m.cons_changes(m.md_table(reg_text, "| ID | Kind |"))
    table = ["| # | Step | Row | Board and generator | Apply script | Depends on | Release guard | What it changes (the register's item) | State |",
             "|---|---|---|---|---|---|---|---|---|"] + ["| %d | %s | %s | %s | %s | %s | %s | %s | %s |" % c for c in ch]
    lines = text.split("\n")
    i = [k for k, l in enumerate(lines) if l.startswith("| # | Step | Row | ")]
    if len(i) != 1:
        refuse("the page has %d change-list tables, not one" % len(i))
    i = i[0]
    j = i
    while j < len(lines) and lines[j].startswith("|"):
        j += 1
    if any(l.startswith("**The P0 round (record l9t5") for l in lines):
        refuse("the page already carries the P0 note: applied before")
    return "\n".join(lines[:i] + [NOTE, ""] + table + lines[j:]), ch


def applied_state(root):
    """The APPLIED tree (set 30's integration commit 7070f106 wrote the three files): {path: current text} and the change list read from
    them, or None when the register does not yet carry R-220. The applied texts must hold every added row, every edited row, every script
    edit and the page's note verbatim; anything else refuses (a half-applied or edited tree is neither state)."""
    p_reg, p_py, p_page = (os.path.join(root, L4, f) for f in ("DOWNSTREAM-REGISTER.md", "l4e9_power_path.py", "L4-POWER-ARCHITECTURE.md"))
    reg = open(p_reg, encoding="utf-8").read()
    if "| R-220 |" not in reg:
        return None
    py = open(p_py, encoding="utf-8").read()
    page = open(p_page, encoding="utf-8").read()
    # The applied tree is authoritative once the rows exist: later record rounds (set 31's restatement of the page, the register and the
    # generator's data) may edit the applied texts, so the test is the PRESENCE of every row this draft adds (by id) and of the page's P0
    # note, not the verbatim text; the change list is then read from the tree's own register and script.
    ids = [re.match(r"\| (R-\d+) \|", r).group(1) for _a, rows in REG_ADD for r in rows]
    missing = [i for i in ids if "| %s |" % i not in reg]
    if missing or not any(l.startswith("**The P0 round (record l9t5") for l in page.split("\n")):
        refuse("the register carries R-220 but not every row this draft adds, or the page lacks the P0 note: %r" % missing[:5])
    m = module_of(py, p_py)
    ch = m.cons_changes(m.md_table(reg, "| ID | Kind |"))
    m.ALREADY_APPLIED = True
    return {p_reg: reg, p_py: py, p_page: page}, ch, m


def patch_all(root):
    """{relative path: new text} and the patched change list, all in memory; on the APPLIED tree (after the integrator wrote the files)
    the tree's own texts and their change list (applied_state), so readers of the list work before and after the integration"""
    done = applied_state(root)
    if done is not None:
        return done
    p_reg, p_py, p_page = (os.path.join(root, L4, f) for f in ("DOWNSTREAM-REGISTER.md", "l4e9_power_path.py", "L4-POWER-ARCHITECTURE.md"))
    reg = patch_register(open(p_reg, encoding="utf-8").read())
    py = patch_script(open(p_py, encoding="utf-8").read())
    try:
        m = module_of(py, p_py)
        page, ch = patch_page(open(p_page, encoding="utf-8").read(), m, reg)
    except SystemExit as e:
        refuse("L4-E9's own change list refuses the patched rows (exit %s)" % e.code)
    return {p_reg: reg, p_py: py, p_page: page}, ch, m


def main(argv):
    args = [a for a in argv if not a.startswith("--")]
    flags = [a for a in argv if a.startswith("--")]
    if len(args) > 1 or any(f not in ("--check", "--write") for f in flags) or len(flags) > 1:
        sys.stderr.write(__doc__.split("Usage:")[1].split("\n")[0] + "\n")
        return 2
    root = os.path.abspath(args[0]) if args else REPO
    files, ch, _m = patch_all(root)
    new = [c for c in ch if re.match(r"R-\d+$", c[2]) and 220 <= int(c[2][2:]) <= 245]
    applied = getattr(_m, "ALREADY_APPLIED", False)
    print("%s: %d changes in the %s list (%d rows R-220 to R-245, R-240 already in the tree, no R-241: route B2 out of the baseline), FAN_OK's three WITHDRAWN, every order constraint holds" % (
        NAME, len(ch), "applied" if applied else "patched", len(new)))
    if applied:
        if flags == ["--write"]:
            refuse("the register already carries R-220: applied before")
        print("%s: APPLIED BEFORE (the tree carries every row this draft adds and the page's P0 note; the change list is read from the tree), nothing to write" % NAME)
        return 0
    if flags != ["--write"]:
        print("%s: CHECK OK, nothing written" % NAME)
        return 0
    for p, t in files.items():
        open(p, "w", encoding="utf-8").write(t)
    for p, t in files.items():
        if open(p, encoding="utf-8").read() != t:
            refuse("%s does not read back as the patched text" % p)
    print("%s: WRITTEN, three files" % NAME)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
